-- P13-02 (2026-11-25) — FINCLUDIA Academy, progression (sections 22 and 23 of the
-- pedagogical referential), GENERATED by a script:
--   - the integrative case of each thematic path, its corrected answer and its
--     weighted grid (pass mark 75 %, no critical error);
--   - the case answers of each person;
--   - the entry test of a path (one question per module, drawn from its bank):
--     at 85 % or more, the fundamental modules answered right are exempted,
--     except security, compliance and active regulation;
--   - the date the exercise was last written (a QCM under 60 % asks for it again).

ALTER TABLE `fin_skill_records` ADD COLUMN `exerciseSavedAt` DATETIME(3) NULL;
ALTER TABLE `fin_skill_records` ADD COLUMN `exempt` BOOLEAN NOT NULL DEFAULT false;

CREATE TABLE `fin_academy_cases` (
    `id` VARCHAR(191) NOT NULL,
    `formationId` VARCHAR(191) NOT NULL,
    `courseId` VARCHAR(191) NOT NULL,
    `title` VARCHAR(190) NOT NULL,
    `scenario` TEXT NOT NULL,
    `tasks` TEXT NOT NULL,
    `correction` TEXT NOT NULL,
    `criteria` JSON NOT NULL,
    `contentVersion` VARCHAR(20) NOT NULL,

    UNIQUE INDEX `fin_academy_cases_formationId_key`(`formationId`),
    UNIQUE INDEX `fin_academy_cases_courseId_key`(`courseId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `fin_academy_cases` ADD CONSTRAINT `fin_academy_cases_formationId_fkey` FOREIGN KEY (`formationId`) REFERENCES `formations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_academy_cases` ADD CONSTRAINT `fin_academy_cases_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE `fin_case_records` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `caseId` VARCHAR(191) NOT NULL,
    `answer` TEXT NOT NULL,
    `ratings` JSON NULL,
    `criticalError` BOOLEAN NOT NULL DEFAULT false,
    `score` INTEGER NULL,
    `validatedAt` DATETIME(3) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    UNIQUE INDEX `fin_case_records_userId_caseId_key`(`userId`, `caseId`),
    INDEX `fin_case_records_caseId_idx`(`caseId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `fin_case_records` ADD CONSTRAINT `chk_case_record_score` CHECK (`score` IS NULL OR `score` BETWEEN 0 AND 100);
ALTER TABLE `fin_case_records` ADD CONSTRAINT `fin_case_records_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_case_records` ADD CONSTRAINT `fin_case_records_caseId_fkey` FOREIGN KEY (`caseId`) REFERENCES `fin_academy_cases`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE `fin_pretests` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `formationId` VARCHAR(191) NOT NULL,
    `questions` JSON NOT NULL,
    `score` INTEGER NULL,
    `exempted` JSON NULL,
    `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `submittedAt` DATETIME(3) NULL,

    INDEX `fin_pretests_userId_formationId_idx`(`userId`, `formationId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `fin_pretests` ADD CONSTRAINT `chk_pretest_score` CHECK (`score` IS NULL OR `score` BETWEEN 0 AND 100);
ALTER TABLE `fin_pretests` ADD CONSTRAINT `fin_pretests_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_pretests` ADD CONSTRAINT `fin_pretests_formationId_fkey` FOREIGN KEY (`formationId`) REFERENCES `formations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('717c599d-8be2-572a-a30f-ff635704ddee', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'Fondamentaux, budget & résilience', 'Samir, jeune actif à Alger, reçoit 92 000 DA nets par mois. Ses dépenses essentielles moyennes sont de 58 000 DA. Il rembourse 12 000 DA de crédit, prévoit 96 000 DA de dépenses annuelles irrégulières, dispose de 75 000 DA de liquidités et veut constituer 300 000 DA pour une formation dans 18 mois. Une hausse fictive de 6 % de certains prix est testée comme scénario pédagogique.', '1. Construire le budget mensuel après mensualisation des dépenses annuelles.
2. Calculer le reste disponible après dépenses essentielles, dette et provision.
3. Calculer le nombre de mois de réserve actuelle.
4. Proposer une contribution mensuelle à l’objectif formation compatible avec le budget.
5. Recalculer le budget sous scénario de +6 % sur 30 000 DA de dépenses sensibles.', 'Provision mensuelle = 96 000/12 = 8 000 DA. Après 58 000 + 12 000 + 8 000, il reste 14 000 DA avant objectif/loisirs. Réserve actuelle = 75 000/58 000 ≈ 1,29 mois. Une contribution de 14 000 DA/mois atteindrait 252 000 DA en 18 mois, donc insuffisante pour 300 000 DA sans autre ressource : il faut augmenter l’horizon, réduire certaines dépenses ou ajouter une ressource. Scénario inflation : 30 000 × 1,06 = 31 800 DA, soit +1 800 DA ; le reste tombe à 12 200 DA.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('e201bb0f-2592-5001-a023-b2516f60626b', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'Banque & inclusion', 'Nadia compare deux comptes fictifs. Offre A : tenue de compte 300 DA/mois, carte 1 200 DA/an, 2 retraits hors réseau gratuits puis 100 DA chacun. Offre B : tenue 450 DA/mois, carte incluse, retraits hors réseau gratuits. Nadia effectue 3 retraits hors réseau par mois et souhaite ensuite simuler un crédit de 360 000 DA sur 24 mois sans conclure automatiquement.', '1. Calculer le coût annuel visible des deux offres pour le comportement décrit.
2. Identifier les éléments à vérifier dans la brochure tarifaire.
3. Expliquer pourquoi la carte, le compte et le budget sont trois notions différentes.
4. Indiquer les contrôles de sécurité avant une opération en ligne.
5. Expliquer ce qu’une simulation de crédit peut et ne peut pas valider.', 'A : tenue 3 600 + carte 1 200 + 12 retraits payants environ (un par mois après les deux gratuits mensuels, donc ici 1 payant/mois) = 1 200 DA, soit 6 000 DA/an. B : 5 400 DA/an. Sur ces seules hypothèses, B est moins chère de 600 DA, mais il faut vérifier tous les autres frais et conditions. La simulation de crédit estime mensualité/coût selon hypothèses ; elle ne vaut ni accord bancaire ni conseil personnalisé.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('9515605b-7ac0-5ade-aea3-7467dd42778c', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'Finance collective & familiale', 'Un couple dispose de 210 000 DA de revenus mensuels (130 000 et 80 000). Les dépenses communes sont de 120 000 DA. Ils veulent partager proportionnellement aux revenus, constituer une réserve commune de 15 000 DA/mois et financer un projet de 360 000 DA en 18 mois.', '1. Calculer la clé de partage proportionnelle.
2. Calculer la quote-part de chacun sur les 120 000 DA.
3. Ajouter la réserve commune et vérifier la capacité du foyer.
4. Calculer la contribution mensuelle nécessaire pour le projet.
5. Proposer une règle de gouvernance en cas de dépense exceptionnelle.', 'Part revenus : 130/210 ≈ 61,9 %, 80/210 ≈ 38,1 %. Dépenses communes : environ 74 286 DA et 45 714 DA. Projet : 360 000/18 = 20 000 DA/mois. Avec réserve 15 000 + projet 20 000, effort commun additionnel 35 000 DA. Une règle de gouvernance peut imposer accord des deux au-delà d’un seuil et justification enregistrée.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('544dc068-5e4e-537e-9916-8890deba2961', '222eb4b1-9a02-5348-b68d-b917a008e63d', '42f119c9-1832-58fe-985e-beb34bfaf582', 'Investissement & marchés', 'Leila dispose fictivement de 600 000 DA qu’elle n’utilisera pas pendant 5 ans. Elle garde séparément son fonds d’urgence. Elle construit un portefeuille pédagogique : 300 000 DA en obligations fictives, 240 000 DA en actions fictives et 60 000 DA en liquidités. Un scénario fait baisser les actions de 25 % et les obligations de 5 %.', '1. Calculer les poids du portefeuille.
2. Calculer la valeur après le scénario adverse.
3. Mesurer la perte totale en DA et en %.
4. Expliquer le rôle de la diversification et ses limites.
5. Identifier les acteurs à consulter pour une exécution réelle en Bourse d’Alger.', 'Poids : obligations 50 %, actions 40 %, liquidités 10 %. Valeur après choc : obligations 285 000 ; actions 180 000 ; liquidités 60 000 = 525 000 DA. Perte = 75 000 DA, soit 12,5 %. La diversification réduit la concentration mais ne supprime pas le risque. Pour une opération réelle, l’utilisateur doit passer par les acteurs/intermédiaires habilités selon le cadre du marché ; FINCLUDIA reste pédagogique.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('4601e952-09a0-57ac-9547-16df8cd12306', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'Professionnels indépendants', 'Une consultante facture 420 000 DA sur un mois mais n’encaisse que 300 000 DA. Ses coûts directs sont de 90 000 DA, ses charges fixes de 140 000 DA et elle réserve 45 000 DA pour obligations fiscales/sociales. Créances clients fin de mois : 180 000 DA.', '1. Distinguer chiffre d’affaires, encaissements et trésorerie.
2. Calculer une marge pédagogique après coûts directs.
3. Calculer le solde de trésorerie simplifié après encaissements, charges fixes, coûts directs et réserve.
4. Expliquer le risque de créances clients.
5. Proposer deux actions de pilotage sans confondre revenu personnel et CA.', 'CA = 420 000 DA ; encaissements = 300 000 DA. Marge après coûts directs = 330 000 DA. Cash simplifié du mois = 300 000 - 90 000 - 140 000 - 45 000 = 25 000 DA avant autres flux. Les 180 000 DA de créances ne sont pas encore du cash. Actions : relance/conditions d’acompte et plan de trésorerie ; rémunération personnelle fixée à partir du cash disponible et non du CA.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('44545489-ce80-5b71-99a5-8b6268316e70', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', '8869d553-57a3-540c-9419-90dc2020a1f6', 'Entrepreneuriat & startup', 'Une startup dispose de 9 M DA de trésorerie. Encaissements mensuels récurrents : 1,2 M DA. Décaissements mensuels : 2,1 M DA. Elle compte 400 clients payants, dépense 600 000 DA/mois en acquisition et envisage une levée de 6 M DA pour 20 % du capital post-opération.', '1. Calculer le burn net mensuel.
2. Calculer le runway avant levée.
3. Calculer le CAC pédagogique du mois si 100 nouveaux clients sont acquis.
4. Calculer la valorisation post-money et pré-money implicites de l’offre.
5. Expliquer les limites de ces indicateurs et les pièces à mettre dans la data room.', 'Burn net = 2,1 - 1,2 = 0,9 M DA/mois. Runway ≈ 9/0,9 = 10 mois. CAC = 600 000/100 = 6 000 DA/nouveau client. Si 6 M représentent 20 % post-money, post-money = 30 M DA et pré-money = 24 M DA. Ces chiffres sont des indicateurs/scénarios ; ils doivent être reliés à churn, marge, croissance, qualité des revenus et documents de gouvernance.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('7b3712b7-c900-5da9-a2f0-cfb13253c373', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'Finance d’entreprise, PME & PMI', 'Une PME réalise 48 M DA de CA annuel. Coûts variables : 28,8 M ; charges fixes : 14,4 M. Stocks : 6 M ; créances clients : 8 M ; dettes fournisseurs : 4 M. Trésorerie disponible : 3 M. Un CAPEX de 5 M DA est envisagé.', '1. Calculer la marge sur coûts variables et son taux.
2. Calculer le seuil de rentabilité simplifié.
3. Calculer le BFR simplifié.
4. Comparer BFR et trésorerie disponible.
5. Dire quelles analyses sont nécessaires avant de lancer le CAPEX.', 'Marge sur coûts variables = 48 - 28,8 = 19,2 M DA, soit 40 %. Seuil de rentabilité = 14,4/0,40 = 36 M DA de CA. BFR = 6 + 8 - 4 = 10 M DA. La trésorerie de 3 M ne couvre pas ce BFR à elle seule. Avant CAPEX : plan 13 semaines, financement, capacité de service de dette, gain de productivité attendu, scénario adverse et priorités de cash.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('70b6ec99-1db7-5f87-bb6f-b1c28a7e5fb9', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'Économie', 'Scénario pédagogique : l’IPC augmente de 5 %, le taux de change DZD/EUR se déprécie de 8 % et le taux directeur augmente. Une famille consacre 40 000 DA/mois à des postes sensibles aux prix ; une PME importe 20 % de ses achats.', '1. Calculer l’effet mécanique de +5 % sur 40 000 DA de dépenses.
2. Expliquer les canaux possibles d’un mouvement de change sur l’entreprise.
3. Expliquer le lien possible entre hausse des taux et crédit.
4. Distinguer PIB nominal et pouvoir d’achat.
5. Identifier les statistiques officielles à consulter avant toute conclusion.', '40 000 × 1,05 = 42 000 DA, soit +2 000 DA si tous les postes suivent exactement le scénario. Une dépréciation peut renchérir les coûts importés en DZD ; une hausse des taux peut affecter le coût/accès au crédit selon le marché et les décisions bancaires. PIB et pouvoir d’achat mesurent des réalités différentes. Les données doivent être sourcées auprès des institutions statistiques et monétaires compétentes.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('790748e2-b8e6-57b9-a81b-285952818dbc', '007c22ab-18bc-5214-82ed-c9bae207558c', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'Diaspora Finance', 'Un membre de la diaspora reçoit 2 600 EUR/mois, dépense 1 700 EUR dans son pays de résidence, transfère 250 EUR à sa famille et affecte 300 EUR/mois à un projet en Algérie. Le reste constitue une marge. Il veut suivre la valeur DZD avec un taux sourcé et daté.', '1. Calculer la marge mensuelle en EUR.
2. Séparer les flux du budget résidence, soutien familial et projet Algérie.
3. Expliquer pourquoi la conversion en DZD ne crée pas un nouveau revenu.
4. Construire un stress de change ±10 %.
5. Définir les preuves à conserver pour le projet Algérie.', 'Marge = 2 600 - 1 700 - 250 - 300 = 350 EUR. Chaque poche doit être suivie séparément. La conversion change l’unité de mesure, pas le revenu économique. Le stress ±10 % doit conserver taux, date et devise d’origine. Les preuves peuvent inclure budget, jalons, documents, justificatifs et validations du projet.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('2c0f2721-f79f-5035-9ab2-ccff27c90faf', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'e24a99a4-d051-5389-8452-61338f9b5072', 'Micro-importation', 'Un auto-entrepreneur prépare un déplacement pédagogique avec 900 000 DA de marchandises, 120 000 DA de voyage/logistique, 45 000 DA de frais divers et 25 000 DA de pertes/risques estimés. Il prévoit 150 unités revendues 9 000 DA pièce. Les limites réglementaires ne sont pas figées dans le cas : elles doivent être lues dans la capsule active.', '1. Calculer le coût complet du lot.
2. Calculer le coût unitaire pédagogique.
3. Calculer le CA potentiel et la marge brute avant autres charges.
4. Vérifier la capsule réglementaire active avant validation du dossier.
5. Identifier les documents et preuves à conserver.', 'Coût complet = 900 000 + 120 000 + 45 000 + 25 000 = 1 090 000 DA. Coût unitaire ≈ 7 266,67 DA. CA potentiel = 1 350 000 DA. Marge brute pédagogique = 260 000 DA avant autres charges/impôts. La conformité ne peut être validée qu’après lecture des paramètres réglementaires actifs et des documents requis.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('a360f703-486a-5b41-8c15-fcf1376978be', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', '99859b96-247e-52a0-890c-38d07aa456b0', 'Commerce international', 'Une PME algérienne achète fictivement 50 000 EUR de marchandise. Fret : 4 000 EUR, assurance : 500 EUR. Taux pédagogique à la date du devis : 150 DZD/EUR. Frais locaux estimés : 900 000 DA. Un scénario teste +10 % sur le taux de change avant paiement.', '1. Calculer la valeur achat+fret+assurance en EUR.
2. Calculer l’équivalent DZD au taux initial, puis le coût avec frais locaux.
3. Recalculer sous +10 % de taux de change.
4. Expliquer ce que l’Incoterm règle et ne règle pas.
5. Identifier les contrôles banque/douane/conformité avant exécution.', 'Base EUR = 54 500 EUR. Au taux 150 : 8 175 000 DA ; avec frais locaux = 9 075 000 DA. Taux +10 % = 165 DZD/EUR : base = 8 992 500 DA ; avec frais locaux = 9 892 500 DA, soit +817 500 DA. L’Incoterm répartit obligations/coûts/risques de livraison mais ne remplace ni le contrat, ni le moyen de paiement, ni les règles de change/douane.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
INSERT IGNORE INTO `fin_academy_cases` (`id`, `formationId`, `courseId`, `title`, `scenario`, `tasks`, `correction`, `criteria`, `contentVersion`) VALUES ('c685eac8-703b-559e-9aaa-87e8859d03c1', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'b0e350bc-120a-5925-905a-c930c72d9bc7', 'Rémunération, obligations et décision responsable', 'un salarié développe une activité complémentaire, souhaite comprendre sa fiche de paie, identifier les informations nécessaires à sa situation fiscale, planifier un module Zakat facultatif et comparer un investissement d’efficacité énergétique. Il doit séparer les cadres fiscal, religieux et financier.', 'Repérer brut, retenues et net sur une fiche fictive
Lister les informations à vérifier avant une obligation fiscale
Construire une estimation Zakat pédagogique
Comparer un CAPEX vert', 'Repérer brut, retenues et net sur une fiche fictive : Le budget s’appuie sur le net récurrent ; les éléments exceptionnels restent séparés.
Lister les informations à vérifier avant une obligation fiscale : Statut, activité, base/CA, période, régime, source officielle et date ; ne pas appliquer un taux hors contexte.
Construire une estimation Zakat pédagogique : Séparer avoirs, conditions, nisab/hawl et éléments nécessitant avis qualifié ; documenter la méthode.
Comparer un CAPEX vert : Calculer payback et scénarios d’économies, puis intégrer maintenance, financement et risques.', '[{"label": "Exactitude technique / calculs", "weight": 35}, {"label": "Interprétation et décision", "weight": 25}, {"label": "Gestion du risque / conformité", "weight": 20}, {"label": "Traçabilité et sources", "weight": 10}, {"label": "Clarté de l’explication", "weight": 10}]', 'V10');
